CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY, name text NOT NULL, payload jsonb NOT NULL, dedupe_key text UNIQUE, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, run_after timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS batches (id uuid PRIMARY KEY, name text, tag text, file_count integer DEFAULT 0, status text DEFAULT 'created', estimated_cost_usd numeric(14,2), actual_cost_usd numeric(14,2), total_count integer DEFAULT 0, completed_count integer DEFAULT 0, failed_count integer DEFAULT 0, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS properties (id uuid PRIMARY KEY, apn text, apn_key text, fips_county text, address_line1 text, city text, state text, zip5 text, address_key text, address_hash text, lat numeric(10,7), lng numeric(10,7), property_type text, beds numeric(5,2), baths numeric(5,2), sqft numeric(12,2), lot_sqft numeric(12,2), year_built integer, units integer, pipeline_status text DEFAULT 'new', tags text[] DEFAULT '{}', next_action text, next_action_date date, gut_rating integer, is_watchlisted boolean DEFAULT false, merged_into_id uuid REFERENCES properties(id), underwriting_status text, last_recomputed_at timestamptz, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS owners (id uuid PRIMARY KEY, full_name text NOT NULL, name_normalized text NOT NULL, entity_type text, mailing_address text, is_absentee boolean, phone text, email text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS property_owners (property_id uuid REFERENCES properties(id), owner_id uuid REFERENCES owners(id), ownership_start_date date, ownership_end_date date, vesting text, ownership_pct numeric(7,6), is_current boolean, acquired_via text, PRIMARY KEY(property_id, owner_id));
CREATE TABLE IF NOT EXISTS reports (id uuid PRIMARY KEY, batch_id uuid REFERENCES batches(id), property_id uuid REFERENCES properties(id), report_type text, vendor text, generated_date date, file_path text NOT NULL, ocr_path text, sha256 text UNIQUE NOT NULL, page_count integer, is_scanned boolean DEFAULT false, ocr_applied boolean DEFAULT false, duplicate_of uuid REFERENCES reports(id), status text DEFAULT 'uploaded', classification_confidence numeric(5,4), created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS extraction_units (id uuid PRIMARY KEY, report_id uuid REFERENCES reports(id), unit_type text NOT NULL, page_start integer NOT NULL, page_end integer NOT NULL, text_path text, token_estimate integer DEFAULT 0, status text DEFAULT 'queued', model text, prompt_version text, cost_usd numeric(14,2), created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS document_signatures (id uuid PRIMARY KEY, pattern text NOT NULL, report_type text NOT NULL, vendor text, priority integer DEFAULT 0, is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS extracted_facts (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), report_id uuid REFERENCES reports(id), extraction_unit_id uuid REFERENCES extraction_units(id), entity_type text NOT NULL, entity_local_id text NOT NULL, field_path text NOT NULL, value_raw text, value_parsed numeric(20,6), value_text text, value_date date, value_bool boolean, unit text, as_of_date date, page_number integer NOT NULL, snippet text NOT NULL, extraction_confidence numeric(5,4) NOT NULL, null_reason text, source_kind text NOT NULL, is_active boolean DEFAULT true, superseded_by uuid REFERENCES extracted_facts(id), created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS extracted_facts_property_field_idx ON extracted_facts(property_id, field_path);
CREATE TABLE IF NOT EXISTS field_resolutions (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), field_path text NOT NULL, winning_fact_id uuid REFERENCES extracted_facts(id), method text NOT NULL, score numeric(10,6), candidate_fact_ids uuid[] DEFAULT '{}', has_conflict boolean DEFAULT false, conflict_magnitude numeric(20,6), verification_state text DEFAULT 'unverified', UNIQUE(property_id, field_path));
CREATE TABLE IF NOT EXISTS mortgages (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), position text, lender_raw text, lender_normalized text, original_amount numeric(14,2), origination_date date, recording_date date, recording_doc_number text, term_months integer, interest_rate numeric(7,6), rate_type text, estimated_balance numeric(14,2), balance_method text, balance_as_of date, is_open boolean, confidence numeric(5,4), primary_fact_id uuid REFERENCES extracted_facts(id));
CREATE TABLE IF NOT EXISTS liens (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), owner_id uuid REFERENCES owners(id), lien_type text, creditor_raw text, creditor_normalized text, amount numeric(14,2), amount_is_estimated boolean, recording_date date, recording_doc_number text, status text, attachment_basis text NOT NULL, attachment_confidence numeric(5,4) NOT NULL, attachment_verified_by text, attachment_verified_at timestamptz, priority_position integer, confidence numeric(5,4), primary_fact_id uuid REFERENCES extracted_facts(id));
CREATE TABLE IF NOT EXISTS foreclosure_events (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), event_type text, event_date date, trustee_name text, trustee_phone text, trustee_sale_number text, original_sale_date date, current_sale_date date, published_bid numeric(14,2), default_amount numeric(14,2), default_as_of date, beneficiary text, stage_after_event text, confidence numeric(5,4));
CREATE TABLE IF NOT EXISTS bankruptcy_events (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), owner_id uuid REFERENCES owners(id), chapter text, case_number text, court text, filing_date date, status text, discharge_date date, filing_sequence integer, is_repeat boolean);
CREATE TABLE IF NOT EXISTS valuations (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), valuation_type text, value numeric(14,2), value_low numeric(14,2), value_high numeric(14,2), confidence_reported numeric(5,4), as_of_date date, source_report_id uuid REFERENCES reports(id), weight_applied numeric(10,6), is_active boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS listings (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), list_date date, delist_date date, list_price numeric(14,2), final_price numeric(14,2), status text, dom integer, mls_number text);
CREATE TABLE IF NOT EXISTS comparable_sales (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), comp_address text, sale_date date, sale_price numeric(14,2), sqft numeric(12,2), beds numeric(5,2), baths numeric(5,2), distance_miles numeric(8,3), price_per_sqft numeric(14,2), similarity_score numeric(8,6), included boolean, exclusion_reason text);
CREATE TABLE IF NOT EXISTS assumption_sets (id uuid PRIMARY KEY, name text NOT NULL, is_default boolean DEFAULT false, params jsonb NOT NULL, version integer NOT NULL, effective_from date NOT NULL);
CREATE TABLE IF NOT EXISTS deal_scenarios (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), strategy text, scenario text, assumption_set_id uuid REFERENCES assumption_sets(id), engine_version text, purchase_price numeric(14,2), arv numeric(14,2), repairs numeric(14,2), holding numeric(14,2), financing numeric(14,2), resale numeric(14,2), all_in_basis numeric(14,2), profit numeric(14,2), roi numeric(10,6), margin_of_safety numeric(10,6), cap_rate numeric(10,6), cash_flow numeric(14,2), coc numeric(10,6), mao numeric(14,2), status text, unavailable_reason text, computed_at timestamptz);
CREATE TABLE IF NOT EXISTS offer_scenarios (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), offer_price numeric(14,2), scenario text, confirmed_payoffs numeric(14,2), potential_payoffs numeric(14,2), closing_costs numeric(14,2), proceeds_low numeric(14,2), proceeds_expected numeric(14,2), proceeds_high numeric(14,2), buyer_basis numeric(14,2), profit numeric(14,2), roi numeric(10,6), is_short_sale boolean);
CREATE TABLE IF NOT EXISTS scoring_configs (id uuid PRIMARY KEY, weights jsonb, bounds jsonb, distress_points jsonb, gates jsonb, version integer, is_active boolean);
CREATE TABLE IF NOT EXISTS scores (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), scoring_config_id uuid REFERENCES scoring_configs(id), fos numeric(10,6), distress numeric(10,6), data_confidence numeric(10,6), risk numeric(10,6), overall numeric(10,6), components jsonb, gates_applied text[], computed_at timestamptz);
CREATE TABLE IF NOT EXISTS rankings (id uuid PRIMARY KEY, scope_type text, scope_id uuid, property_id uuid REFERENCES properties(id), rank integer, prev_rank integer, score numeric(10,6), ranked_at timestamptz);
CREATE TABLE IF NOT EXISTS flags (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), flag_type text, payload jsonb, financial_impact_usd numeric(14,2), status text, resolution text, resolved_value jsonb, note text, resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS change_events (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), change_type text, field_path text, old_value jsonb, new_value jsonb, source_report_id uuid REFERENCES reports(id), score_delta numeric(10,6), detected_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS property_notes (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), body text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS realized_deals (id uuid PRIMARY KEY, property_id uuid REFERENCES properties(id), purchase_price numeric(14,2), actual_repairs numeric(14,2), actual_holding_days integer, sale_price numeric(14,2), actual_costs numeric(14,2), outcome text, notes text, closed_at date);
CREATE TABLE IF NOT EXISTS settings (key text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS history (id uuid PRIMARY KEY, entity_type text, entity_id uuid, action text, before jsonb, after jsonb, at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS saved_views (id uuid PRIMARY KEY, name text, filters jsonb, columns jsonb, created_at timestamptz DEFAULT now());
